t.script:
/* Category pills, live search and one-tap Add to cart (Odoo 20 JSON route /shop/cart/add) */
document.addEventListener('DOMContentLoaded', function () {
    const shop = document.querySelector('.rc-shop');
    if (!shop) { return; }
    const cards = Array.from(shop.querySelectorAll('.rc-card'));
    const sections = Array.from(shop.querySelectorAll('.rc-cat-section'));
    const empty = shop.querySelector('.rc-empty');
    let activeCat = 'all';
    function applyFilter() {
        const q = (shop.querySelector('.rc-search input').value || '').trim().toLowerCase();
        let shown = 0;
        cards.forEach(function (c) {
            const catOk = activeCat === 'all' || c.dataset.cat === activeCat; const textOk = !q || c.dataset.name.indexOf(q) !== -1; const ok = catOk ? textOk : false;
            c.style.display = ok ? '' : 'none';
            if (ok) { shown++; }
        });
        sections.forEach(function (s) {
            s.style.display = s.querySelector('.rc-card:not([style*="none"])') ? '' : 'none';
        });
        empty.style.display = shown ? 'none' : 'block';
    }
    shop.querySelectorAll('.rc-pill').forEach(function (p) {
        p.addEventListener('click', function () {
            shop.querySelectorAll('.rc-pill').forEach(function (x) { x.classList.remove('active'); });
            p.classList.add('active');
            activeCat = p.dataset.cat;
            applyFilter();
        });
    });
    shop.querySelector('.rc-search input').addEventListener('input', applyFilter);

    const toast = shop.querySelector('.rc-toast');
    shop.querySelectorAll('.rc-add[data-product-id]').forEach(function (btn) {
        btn.addEventListener('click', function () {
            btn.disabled = true;
            fetch('/shop/cart/add', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ jsonrpc: '2.0', method: 'call', params: {
                    product_template_id: parseInt(btn.dataset.templateId), product_id: parseInt(btn.dataset.productId), quantity: 1 } })
            }).then(function (r) { return r.json(); }).then(function (res) {
                if (res.error) { throw res.error; }
                const qty = res.result ? (res.result.cart_quantity || res.result.quantity) : 0;
                document.querySelectorAll('.my_cart_quantity').forEach(function (el) {
                    if (qty) { el.textContent = qty; } el.classList.remove('d-none');
                });
                btn.classList.add('rc-added'); btn.querySelector('i').className = 'fa fa-check';
                toast.querySelector('span').textContent = btn.dataset.name + ' added to your cart';
                toast.classList.add('show'); setTimeout(function () { toast.classList.remove('show'); }, 3200);
                setTimeout(function () { btn.classList.remove('rc-added'); btn.querySelector('i').className = 'fa fa-shopping-bag'; btn.disabled = false; }, 1800);
            }).catch(function () { window.location.href = btn.dataset.url; });
        });
    });
});
